#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by the Eminzo installer from the files found in the repo: review it.
set -e

# The checks: install the locked dev dependencies, then lint, typecheck, test and build, each
# step on its own so the first failure stops the script (set -e) and names the failing step.
#
# Scoped checks (optional). The factory sets two variables:
#   FACTORY_CHECK_MODE     "focused" while a builder iterates (factory/bin/nudge <job-id>);
#                          "full" for the Stop hook, 'nudge --full', the gate and the merge.
#   FACTORY_CHANGED_FILES  with focused: the path of a file that lists what the branch changed
#                          against its base, ONE repo-relative path per line (so a path may hold
#                          spaces), sorted, deleted files included, a rename as old and new path.
#                          Not set in full mode.
# Limits of the list: a submodule bump shows only as the submodule's path, files in ignored
# directories are never listed, and if a path holds a newline the factory runs full instead.
# A checks.sh that ignores both variables runs everything, which is always safe. The gate always
# runs full mode, so a focused pass is a shortcut for the builder and the full run is the backstop.
#
# Affected-only checks (optional, for a monorepo). The factory also sets:
#   FACTORY_BASE  the commit the job's branch left the base at, for the gate, the merge and the builder's focused nudge (not nudge --full or the Stop hook).
#   FACTORY_HEAD  the commit under test, for the gate and the merge (not the nudge).
# Neither is set when you run this file by hand or the job fixes the base: check everything then.
MODE="${FACTORY_CHECK_MODE:-full}"
CHANGED="${FACTORY_CHANGED_FILES:-}"
# Read once, then unset, so a test that starts another check process does not inherit them.
unset FACTORY_CHECK_MODE FACTORY_CHANGED_FILES

if [ "$MODE" = focused ] && [ -n "$CHANGED" ] && [ -s "$CHANGED" ]; then
  # A diff with only docs may skip the checks; say so in the log. Only docs/ and a top-level
  # CHANGELOG.md count here. README.md and factory/project.md do not: test/docs.test.ts reads them.
  # Any grep error (status 2) falls through and runs everything.
  rc=0
  grep -qvE '^(docs/|CHANGELOG\.md$)' "$CHANGED" || rc=$?
  if [ "$rc" -eq 1 ]; then
    echo "factory/checks.sh: only docs changed; skipping the checks (focused mode)"
    exit 0
  fi
  # Any other change runs the full checks below.
fi

# Full mode, and any focused change not skipped above: run everything. --ignore-scripts: no
# dependency needs an install script (the native binaries come as optional packages).
npm ci --ignore-scripts --no-audit --no-fund
npm run lint
npm run typecheck
npm test
npm run build
